/*	Decides whether the submission is genuine and prepares the wording.
	Somebody reaches an event two ways: they accept an invitation and are assigned here,
	or a coordinator staffs them first and the invitation goes out through Email to Staff.
	Both are supported, and either can be withdrawn by declining.
	A fourth answer, unable, is not a decision - it is the invited person reporting that
	their record is missing what the event needs.
	Role names, the verb and email styling all come from Config, never hardcoded	*/

const cfg = $('Config').first().json;
const sub = $('Extract submission').first().json;
const api = $json;

const event = (api.data || {}).event || null;
const responder = (api.data || {}).responder || null;

const staff = (((event || {}).staff || {}).edges || []).map(e => e.node);
const coordRole = String(cfg.COORDINATOR_ROLE_NAME).trim();
const fallbackRole = String(cfg.FALLBACK_ROLE_NAME || 'Instructor').trim();

/*	The verb for what an instructor does with an event. The literal is a last resort if
	config is blank, not the setting - change VERB_BASE in Config	*/
const verb = String(cfg.VERB_BASE || 'deliver').trim();

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const page = (title, body) => '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>' + cfg.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc(cfg.BRAND_NAME) + '</p></header><main>' + body + '</main></body></html>';

/*	The email frame, button and palette live in Config, so the look is changed in one
	place. Pipe separated because the font list itself contains commas	*/
const pal = {};
for (const part of String(cfg.EMAIL_PALETTE || '').split('|')) {
	const at = part.indexOf('=');
	if (at > 0) { pal[part.slice(0, at).trim()] = part.slice(at + 1).trim(); }
}

/*	Palette tokens first, then the content, so a colour name appearing inside the body
	cannot be substituted twice	*/
const fill = (tpl, extra) => {
	let s = String(tpl || '');
	for (const k of Object.keys(pal)) { s = s.split('%%' + k + '%%').join(pal[k]); }
	for (const k of Object.keys(extra || {})) { s = s.split('%%' + k + '%%').join(extra[k]); }
	return s;
};

const emailShell = (inner) => fill(cfg.EMAIL_SHELL, { BRAND: esc(cfg.BRAND_NAME), BODY: inner });
const quoteBlock = (text) => '<div style="border-left:3px solid ' + pal.LINE + ';padding:2px 0 2px 14px;margin:0 0 16px;color:' + pal.MUTED + ';font-style:italic;">' + esc(text) + '</div>';

const NOOP = JSON.stringify({ query: 'query NoOp { __typename }' });
const blockedHeading = 'Answer cannot be recorded yet';

const shell = (heading, message, cls, tail) => ({
	valid: false,
	isUnable: false,
	isDeclined: false,
	staffId: '',
	notifyContactIds: [],
	coordinatorContactIds: [],
	rejectionHtml: page(heading, '<h1>' + esc(heading) + '</h1><div class="' + cls + '"><p>' + esc(message) + '</p></div><p>' + tail + '</p>'),
	assignBody: NOOP
});

const refuse = (heading, message) => [{ json: shell(heading, message, 'notice error', 'Please reply to the invitation email and someone will help.') }];
const closeOff = (heading, message) => [{ json: shell(heading, message, 'notice', 'You can close this page.') }];

const answerOk = ['yes', 'no', 'maybe', 'unable'].indexOf(sub.answer) !== -1;

if (!event || !responder) { return refuse('We could not record that response', 'This invitation may have been withdrawn, or the link may be incomplete.'); }
if (!answerOk) { return refuse('We could not record that response', 'That answer was not one of the options offered.'); }

const isUnable = sub.answer === 'unable';

const onBehalf = sub.onBehalf === 'true';
const clicker = staff.find(s => s.contact && s.contact.id === sub.contactId) || null;
const clickerIsCoordinator = clicker !== null && String((clicker.staffRole || {}).name || '').trim() === coordRole;

if (onBehalf && !clickerIsCoordinator) {
	return refuse('Only the ' + coordRole + ' can record that', 'Recording an answer on somebody else\u2019s behalf is done by the ' + coordRole + ' for that event.');
}

const myStaff = staff.find(s => s.contact
	&& s.contact.id === responder.id
	&& String((s.staffRole || {}).name || '').trim() !== coordRole) || null;

const alreadyOn = myStaff !== null;
const staffId = alreadyOn ? myStaff.id : '';
const staffedRole = alreadyOn ? String((myStaff.staffRole || {}).name || '').trim() : '';

let requiredRoleCount = 0;
const requiredOpen = [];

for (const req of (event.requiredStaff || [])) {
	const roleName = String((req.staffRole || {}).name || '').trim();
	const roleId = String((req.staffRole || {}).id || '');
	const qty = Number(req.quantity || 0);
	if (roleName === coordRole || qty === 0) { continue; }
	requiredRoleCount = requiredRoleCount + 1;
	const holders = staff.filter(s => String((s.staffRole || {}).name || '').trim() === roleName);
	if (holders.length < qty) { requiredOpen.push({ id: roleId, name: roleName }); }
}

const slotsFilled = requiredRoleCount > 0 && requiredOpen.length === 0;
const neededRole = requiredOpen.length > 0 ? requiredOpen[0].name : fallbackRole;

const myRoleIds = (responder.staffRoles || []).map(r => String(r.id));
const holdableOpen = requiredOpen.filter(r => myRoleIds.indexOf(r.id) !== -1);
const fallbackRoleId = String(cfg.FALLBACK_ROLE_ID);

const targetRole = requiredRoleCount === 0
	? (myRoleIds.indexOf(fallbackRoleId) !== -1 ? { id: fallbackRoleId, name: fallbackRole } : null)
	: (holdableOpen.length > 0 ? holdableOpen[0] : null);

const missingRole = targetRole === null;
const notEligible = responder.isInstructor !== true && responder.isQualified !== true;

const blockedReason = missingRole
	? 'This event needs a ' + neededRole + ', and your contact record does not have that role yet. Until it is added, an answer cannot be saved against the event.'
	: 'Your contact record is not marked as able to ' + verb + ' events yet. Until that is set, an answer cannot be saved against the event.';

if (!isUnable && !onBehalf && !alreadyOn && notEligible) {
	return refuse(blockedHeading, blockedReason);
}

if (sub.answer === 'yes' && slotsFilled && !alreadyOn) {
	return closeOff('This event is now fully staffed', 'Somebody else accepted before we heard from you, so no response is needed. Thank you for considering it.');
}

if (sub.answer === 'yes' && !alreadyOn && missingRole) {
	return refuse(blockedHeading, blockedReason);
}

const name = responder.firstName + ' ' + responder.lastName;
const now = new Date().toISOString();
const roleLabel = staffedRole || (targetRole ? targetRole.name : neededRole);

const coordinatorContactIds = staff
	.filter(s => s.contact && String((s.staffRole || {}).name || '').trim() === coordRole)
	.map(s => s.contact.id);

const hasCoordinator = coordinatorContactIds.length > 0;

const notifyContactIds = coordinatorContactIds.slice();
if (notifyContactIds.indexOf(responder.id) === -1) { notifyContactIds.push(responder.id); }

const labels = {
	yes: cfg.ANSWER_LABEL_YES,
	no: cfg.ANSWER_LABEL_NO,
	maybe: cfg.ANSWER_LABEL_MAYBE,
	unable: cfg.ANSWER_LABEL_UNABLE
};

const statuses = { yes: 'accepted', no: 'declined', maybe: 'maybe', unable: 'assign_failed' };
const logStatuses = { yes: 'success', no: 'success', maybe: 'pending', unable: 'failed' };

const answerLabel = labels[sub.answer];
const behalfNote = onBehalf ? ' Recorded by the ' + coordRole + ' on their behalf.' : '';
const quoted = sub.comments ? quoteBlock(sub.comments) : '<p style="margin:0 0 16px;color:' + pal.MUTED + ';">No comments were added.</p>';

const shouldAssign = sub.answer === 'yes' && !alreadyOn && targetRole !== null;
const isDeclined = sub.answer === 'no' && alreadyOn;

const assignBody = shouldAssign
	? JSON.stringify({
		query: 'mutation AssignToEvent($eventId: ID!, $contactId: ID!, $roleId: ID!){ event { addStaff(input:{ eventId:$eventId, contactId:$contactId, staffRoleId:$roleId }){ errors{ label message value } } } }',
		variables: { eventId: event.id, contactId: responder.id, roleId: targetRole.id }
	})
	: NOOP;

/*	The coordinator and the responder both read this one, so it is written in the third
	person. The answer is the thing they are looking for, so it leads	*/
const emailSubject = name + ' - ' + answerLabel + ' - ' + event.title;

const answerColour = sub.answer === 'yes' ? pal.ACCENT : (sub.answer === 'no' ? pal.DANGER : pal.MUTED);

const emailBody = emailShell(
	'<p style="margin:0 0 6px;color:' + pal.MUTED + ';font-size:13px;">Response recorded</p>'
	+ '<p style="margin:0 0 4px;font-size:20px;font-weight:600;color:' + pal.INK + ';">' + esc(name) + '</p>'
	+ '<p style="margin:0 0 18px;font-size:16px;font-weight:600;color:' + answerColour + ';">' + esc(answerLabel) + '</p>'
	+ '<p style="margin:0 0 6px;">Invitation to ' + esc(verb) + ' <strong>' + esc(event.title) + '</strong>.' + esc(behalfNote) + '</p>'
	+ '<p style="margin:18px 0 8px;color:' + pal.MUTED + ';font-size:13px;">Comments</p>' + quoted
	+ (shouldAssign ? '<p style="margin:0 0 16px;">' + esc(name) + ' is now assigned to the event as ' + esc(roleLabel) + '.</p>' : '')
	+ (isDeclined ? '<p style="margin:0 0 16px;">' + esc(name) + ' has been taken off the event.</p>' : '')
	+ '<p style="margin:20px 0 8px;padding-top:14px;border-top:1px solid ' + pal.LINE + ';color:' + pal.MUTED + ';font-size:13px;">This note goes to the ' + esc(coordRole) + ' and to the person who answered.</p>');

const failSubject = 'Action needed: ' + name + ' cannot be added to ' + event.title;

const failOpening = isUnable
	? '<p style="margin:0 0 16px;"><strong>' + esc(name) + '</strong> opened the invitation to ' + esc(verb) + ' <strong>' + esc(event.title) + '</strong> and could not answer it, because their contact record does not carry the ' + esc(neededRole) + ' role this event needs.</p>' + (sub.comments ? '<p style="margin:0 0 8px;color:' + pal.MUTED + ';font-size:13px;">They added</p>' + quoted : '')
	: '<p style="margin:0 0 16px;"><strong>' + esc(name) + '</strong> accepted the invitation to ' + esc(verb) + ' <strong>' + esc(event.title) + '</strong>, but Administrate refused to assign them as ' + esc(roleLabel) + '.</p>';

const failBody = emailShell(
	'<p style="margin:0 0 6px;color:' + pal.DANGER + ';font-size:13px;font-weight:600;">Action needed</p>'
	+ '<p style="margin:0 0 18px;font-size:20px;font-weight:600;color:' + pal.INK + ';">' + esc(name) + ' cannot be added</p>'
	+ failOpening
	+ '<p style="margin:0 0 16px;">They have not been added to the event, and they have been told somebody will be in touch.</p>'
	+ '<div style="background:' + pal.DANGERBG + ';border-left:3px solid ' + pal.DANGER + ';padding:12px 14px;margin:0 0 16px;">'
	+ '<p style="margin:0;"><strong>To fix it:</strong> open their contact record in Administrate, add the ' + esc(roleLabel) + ' role, then ask them to open their personal response link again.</p></div>'
	+ '<p style="margin:0 0 16px;color:' + pal.MUTED + ';">If they were invited by mistake, nothing needs doing. Nothing on the event has been changed.</p>');

const thanksSelf = sub.answer === 'yes'
	? '<h1>Thank you, you are confirmed</h1><div class="notice"><p>You are ' + (alreadyOn ? 'confirmed to ' + esc(verb) : 'now assigned to ' + esc(verb)) + ' <strong>' + esc(event.title) + '</strong>.' + (hasCoordinator ? ' The ' + esc(coordRole) + ' has been told.' : '') + '</p></div>'
	: (sub.answer === 'no'
		? '<h1>Thank you for letting us know</h1><div class="notice"><p>We have recorded that you are not available for <strong>' + esc(event.title) + '</strong>' + (isDeclined ? ', and you have been taken off it' : '') + '. We will ask someone else.</p></div>'
		: '<h1>Thank you, we will be in touch</h1><div class="notice"><p>We have recorded your response about <strong>' + esc(event.title) + '</strong>. Your link stays open, so you can give a firm answer whenever you are ready.</p></div>');

const thanksBehalf = '<h1>Response recorded</h1><div class="notice"><p>' + esc(answerLabel) + ' recorded for <strong>' + esc(name) + '</strong> on ' + esc(event.title) + '.'
	+ (shouldAssign ? ' They have been assigned to the event.' : '')
	+ (isDeclined ? ' They have been removed from the event.' : '') + '</p></div>';

const unassignedInner = isUnable
	? (hasCoordinator
		? '<h1>Thank you, we have passed this on</h1><div class="notice"><p>The ' + esc(coordRole) + ' for <strong>' + esc(event.title) + '</strong> knows the ' + esc(neededRole) + ' role needs adding to your record, and will be in touch.</p></div>'
		: '<h1>Thank you, we have recorded this</h1><div class="notice"><p>This event has no ' + esc(coordRole) + ' for us to tell, so please reply to the invitation email for <strong>' + esc(event.title) + '</strong> and somebody will add the ' + esc(neededRole) + ' role to your record.</p></div>')
	: (hasCoordinator
		? '<h1>Thank you, we have your answer</h1><div class="notice"><p>We have recorded that you are available for <strong>' + esc(event.title) + '</strong>. The ' + esc(coordRole) + ' needs to confirm your place, and will be in touch.</p></div>'
		: '<h1>Thank you, we have your answer</h1><div class="notice"><p>We have recorded that you are available for <strong>' + esc(event.title) + '</strong>. This event has no ' + esc(coordRole) + ', so please reply to the invitation email and somebody will confirm your place.</p></div>');

const thanksUnassigned = page('Response recorded', unassignedInner + '<p>You can close this page.</p>');

const failLogMessage = (isUnable
	? 'Cannot assign ' + name + ': their contact record does not carry the ' + neededRole + ' role, which this event requires. Reported by them from the invitation page. No answer recorded and they are not on the event.'
	: 'Cannot assign ' + name + ' as ' + roleLabel + ': Administrate refused the assignment, which means their contact record does not carry that role. Their acceptance is recorded but they are not on the event.')
	+ ' Fix: add the ' + roleLabel + ' role to their contact record, then ask them to open their personal response link again.';

return [{ json: {
	valid: true,
	assigned: shouldAssign,
	isUnable: isUnable,
	isDeclined: isDeclined,
	staffId: staffId,
	targetRoleId: targetRole ? targetRole.id : '',
	neededRole: neededRole,
	hasCoordinator: hasCoordinator,
	coordinatorContactIds: coordinatorContactIds,
	notifyContactIds: notifyContactIds,
	eventId: event.id,
	eventTitle: String(event.title || ''),
	contactId: responder.id,
	contactName: name,
	contactEmail: String(responder.emailAddress || ''),
	staffRole: roleLabel,
	answer: sub.answer,
	answerLabel: answerLabel,
	status: statuses[sub.answer],
	logStatus: logStatuses[sub.answer],
	comments: sub.comments,
	onBehalf: onBehalf,
	channel: onBehalf ? 'coordinator' : 'form',
	submittedBy: onBehalf && clicker ? clicker.contact.firstName + ' ' + clicker.contact.lastName : name,
	now: now,
	assignBody: assignBody,
	emailSubject: emailSubject,
	emailBody: emailBody,
	failSubject: failSubject,
	failBody: failBody,
	logMessage: name + ' responded: ' + answerLabel + (sub.comments ? ' - ' + sub.comments : '') + behalfNote + (shouldAssign ? ' Assigned to the event as ' + roleLabel + '.' : '') + (isDeclined ? ' Removed from the event.' : ''),
	failLogMessage: failLogMessage,
	logPayload: JSON.stringify({ eventId: event.id, contactId: responder.id, answer: sub.answer, comments: sub.comments, assigned: shouldAssign, removed: isDeclined, onBehalf: onBehalf, roleId: targetRole ? targetRole.id : '', neededRole: neededRole, hasCoordinator: hasCoordinator, at: now }),
	thanksHtml: page('Response recorded', (onBehalf ? thanksBehalf : thanksSelf) + '<p>You can close this page.</p>'),
	thanksUnassignedHtml: thanksUnassigned
} }];

/*	Nothing is recorded unless the submission carries the personal token stored on the
	submitter's invitation row. For an on-behalf answer that is the coordinator's own token.
	A request for a personal link needs no token: the link only ever goes to the email
	address on the contact record	*/

const cfg = $('Config').first().json;
const sub = $('Extract submission').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.event_id);
const row = rows.find((r) => String(r.event_id) === String(sub.eventId) && String(r.contact_id) === String(sub.contactId)) || null;

/*	Compares in constant time, so response timing does not leak how much of a guess
	was right. An empty token never matches	*/
const sameToken = (expected, given) => {
	const a = String(expected || '');
	const b = String(given || '');
	if (a === '' || b === '' || a.length !== b.length) { return false; }
	let diff = 0;
	for (let i = 0; i < a.length; i++) { diff = diff | (a.charCodeAt(i) ^ b.charCodeAt(i)); }
	return diff === 0;
};

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const page = (title, body) => '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>' + cfg.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc(cfg.BRAND_NAME) + '</p></header><main>' + body + '</main></body></html>';

const linkRequest = String(sub.action || '') === 'request_link';
const hasIds = String(sub.eventId || '') !== '' && String(sub.contactId || '') !== '';
const valid = !linkRequest && hasIds && row !== null && sameToken(row.token, sub.linkToken);

const invalidHeading = 'This link is invalid or has expired';
const sentHeading = 'Check your email';

return [{ json: {
	linkRequest: linkRequest,
	valid: valid,
	row: row,
	invalidHtml: page(invalidHeading, '<h1>' + esc(invalidHeading) + '</h1><div class="notice error"><p>Your answer was not recorded and nothing has changed.</p></div><p>Open the most recent email we sent you and use the link in it. If you cannot find it, reply to the invitation email and someone will help.</p>'),
	linkSentHtml: page(sentHeading, '<h1>' + esc(sentHeading) + '</h1><div class="notice"><p>If this invitation is still open, we have emailed a personal link to the address we hold for you. It can take a few minutes to arrive.</p></div><p>You can close this page.</p>')
} }];

/*	Somebody opened an invitation without a valid personal link and asked for one.
	The link goes only to the email address on their contact record, so knowing an event
	and contact ID is not enough to answer for somebody else.
	An existing token is reused rather than replaced, so asking again cannot break a link
	already sent. Requests within LINK_RESEND_MINUTES of the last one send nothing.
	The page shown afterwards is the same whatever happens here, so it does not reveal
	whether an event or contact exists	*/

const cfg = $('Config').first().json;
const api = $input.first().json;
const row = $('Check Link Token').first().json.row || null;

const event = (api.data || {}).event || null;
const contact = (api.data || {}).contact || null;

const coordRole = String(cfg.COORDINATOR_ROLE_NAME).trim();
const verb = String(cfg.VERB_BASE || 'deliver').trim();

/*	A random, unguessable token. 32 bytes from a secure source, hex encoded. It is
	never derived from the event or contact ID. Uses the crypto module where the Code
	node allows it, otherwise the Web Crypto API	*/
const randomToken = () => {
	let bytes = null;
	try {
		bytes = Array.from(require('crypto').randomBytes(32));
	} catch (error) {
		if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
			bytes = Array.from(crypto.getRandomValues(new Uint8Array(32)));
		}
	}
	if (!bytes) {
		throw new Error('No secure random source available. Allow the crypto module in Code nodes (NODE_FUNCTION_ALLOW_BUILTIN=crypto).');
	}
	return bytes.map((b) => b.toString(16).padStart(2, '0')).join('');
};

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const pal = {};
for (const part of String(cfg.EMAIL_PALETTE || '').split('|')) {
	const at = part.indexOf('=');
	if (at > 0) { pal[part.slice(0, at).trim()] = part.slice(at + 1).trim(); }
}

const fill = (tpl, extra) => {
	let s = String(tpl || '');
	for (const k of Object.keys(pal)) { s = s.split('%%' + k + '%%').join(pal[k]); }
	for (const k of Object.keys(extra || {})) { s = s.split('%%' + k + '%%').join(extra[k]); }
	return s;
};

const emailShell = (inner) => fill(cfg.EMAIL_SHELL, { BRAND: esc(cfg.BRAND_NAME), BODY: inner });
const emailButton = (url, label) => fill(cfg.EMAIL_BUTTON, { URL: esc(url), LABEL: esc(label) });

const now = new Date();
const nowIso = now.toISOString();
const resendMinutes = Number(cfg.LINK_RESEND_MINUTES || 0);
const lastSent = row && row.link_sent_at ? new Date(String(row.link_sent_at)).getTime() : NaN;
const tooSoon = !isNaN(lastSent) && (now.getTime() - lastSent) < resendMinutes * 60000;
const email = String((contact || {}).emailAddress || '').trim();

if (event === null || contact === null || email === '' || tooSoon) {
	return [{ json: { send: false } }];
}

const staff = ((event.staff || {}).edges || []).map((e) => e.node);
const isCoordinator = staff.some((s) => s.contact
	&& String(s.contact.id) === String(contact.id)
	&& String((s.staffRole || {}).name || '').trim() === coordRole);

const token = row && row.token ? String(row.token) : randomToken();
const name = String((contact.firstName || '') + ' ' + (contact.lastName || '')).trim();
const link = String(cfg.RESPONSE_BASE_URL) + '?e=' + encodeURIComponent(event.id) + '&c=' + encodeURIComponent(contact.id) + '&t=' + encodeURIComponent(token);

const body = emailShell(
	'<p style="margin:0 0 16px;">Hi ' + esc(contact.firstName || name) + ',</p>'
	+ '<p style="margin:0 0 6px;color:' + pal.MUTED + ';font-size:13px;">' + (isCoordinator ? 'Your ' + esc(coordRole) + ' link' : 'Your personal response link') + '</p>'
	+ '<p style="margin:0 0 18px;font-size:20px;font-weight:600;color:' + pal.INK + ';">' + esc(event.title) + '</p>'
	+ '<p style="margin:0 0 4px;">' + (isCoordinator
		? 'Use this link to record responses for this event on behalf of the people invited.'
		: 'Use this link to tell us whether you are available to ' + esc(verb) + ' this event.') + '</p>'
	+ emailButton(link, isCoordinator ? 'Open the event' : 'Give your answer')
	+ '<p style="margin:0 0 16px;color:' + pal.MUTED + ';">This link is personal to you. Please do not forward it.</p>');

/*	A new row starts as invited, or coordinator for the event's coordinator, who is never
	chased or counted. An existing row keeps its status and its age	*/
return [{ json: {
	send: true,
	eventId: String(event.id),
	eventTitle: String(event.title || ''),
	contactId: String(contact.id),
	contactName: name,
	contactEmail: email,
	status: row && row.status ? String(row.status) : (isCoordinator ? 'coordinator' : 'invited'),
	token: token,
	now: nowIso,
	updatedAt: row && row.updated_at ? String(row.updated_at) : nowIso,
	subject: (isCoordinator ? 'Your ' + coordRole + ' link: ' : 'Your response link: ') + String(event.title || ''),
	body: body
} }];
